changeSet.sql:
ALTER TABLE hiv_art_clinical ADD COLUMN IF NOT EXISTS cd4_data jsonb;
CREATE INDEX IF NOT EXISTS idx_art_clinical_cd4_data ON hiv_art_clinical USING gin (cd4_data);
COMMENT ON COLUMN hiv_art_clinical.cd4_data IS 'JSON object containing cd4_result and cd4_date';

-- Migrate existing cd4_date data to cd4_data JSON column before dropping
UPDATE hiv_art_clinical
SET cd4_data = jsonb_build_object('cd4_date', cd4_date)
WHERE cd4_date IS NOT NULL AND (cd4_data IS NULL OR cd4_data = '{}'::jsonb);

-- Drop the cd4_date column as it's now part of cd4_data
ALTER TABLE hiv_art_clinical DROP COLUMN IF EXISTS cd4_date;

-- Drop the index if it exists
DROP INDEX IF EXISTS idx_art_clinical_cd4_date;

-- Create a temporary JSONB column
ALTER TABLE hiv_art_clinical ADD COLUMN IF NOT EXISTS cotrimoxazole_dose_temp JSONB;

-- Migrate existing VARCHAR data to JSONB format
-- Wrap existing dose values in a JSON object with 'dose' key
UPDATE hiv_art_clinical
SET cotrimoxazole_dose_temp = jsonb_build_object('dose', cotrimoxazole_dose)
WHERE cotrimoxazole_dose IS NOT NULL AND cotrimoxazole_dose != '';

-- Drop the old VARCHAR column
ALTER TABLE hiv_art_clinical DROP COLUMN cotrimoxazole_dose;

-- Rename the temporary column to the original name
ALTER TABLE hiv_art_clinical RENAME COLUMN cotrimoxazole_dose_temp TO cotrimoxazole_dose;

-- Update column comment
COMMENT ON COLUMN hiv_art_clinical.cotrimoxazole_dose IS 'Cotrimoxazole (CTX) data stored as JSON containing medication ID and dose';

-- Create GIN index for better JSONB query performance
CREATE INDEX IF NOT EXISTS idx_hiv_art_clinical_cotrimoxazole_dose ON hiv_art_clinical USING GIN(cotrimoxazole_dose) WHERE cotrimoxazole_dose IS NOT NULL;
